use super::*;
use crate::state::tests::{grant,observe,source,drain};
use semio_framework_value::retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
#[test]
fn original_authored_field_sealing_preserves_sources_and_cancels_every_paid_prefix(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let body=law["bodyBytes"].as_u64().unwrap()as usize;let mut texts=law["strings"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<Vec<_>>();texts.push(law["largeText"]["pattern"].as_str().unwrap().repeat(law["largeText"]["repetitions"].as_u64().unwrap()as usize));for text in &texts{for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let input=source(text.to_owned());let pointer=input.borrow().get().as_ptr();let foreign=source("foreign".to_owned());let(mut field,h)=observe(RetainedSealedField::<String>::new);assert_eq!(h,(0,0));let mut turns=0;while !field.ready()&&cut.is_none_or(|cut|turns<cut){let d=field.demand(input.borrow(),body).unwrap();let g=grant(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let(s,h)=observe(||field.advance(input.borrow(),body,denied).unwrap());assert_eq!(s.progress(),RetainedCloneProgress::default());assert_eq!(h,(0,0));assert_eq!(field.demand(input.borrow(),body).unwrap(),d);}let(s,h)=observe(||field.advance(input.borrow(),body,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert_eq!(input.borrow().get().as_ptr(),pointer);assert!(field.demand(foreign.borrow(),body).is_err());turns+=1;assert!(turns<10000);}let mut output=None;if cut.is_none(){assert!(field.ready());let g=grant(field.take_demand().unwrap());let((value,p),h)=observe(||field.take(g).unwrap().unwrap());assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(value.get(),input.borrow().get());if !value.get().is_empty(){assert_ne!(value.get().as_ptr(),pointer);}output=Some(value);}field.begin_close();for _ in 0..100000{if field.terminal_is_empty(){break;}let d=field.close_demand(body).unwrap();let g=grant(d);let(s,h)=observe(||field.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(field.terminal_is_empty());assert_eq!(observe(||drop(field)).1,(0,0));if let Some(value)=output{drain(value);}drain(input);drain(foreign);}}
}

#[test]
fn original_identity_branch_projection_adopts_only_the_paid_name_header(){
 use crate::state::{EnergyModelState,ModelIdentityState};
 let law=crate::state::tests::corpus();let original=source(crate::state::tests::receive::<EnergyModelState>(&law["model"]));let branch=original.borrow().project(0,|m|m.identity.get());let text=source("New original model β".to_owned());let mut field=RetainedSealedField::<String>::new();for _ in 0..10000{if field.ready(){break;}let g=grant(field.demand(text.borrow(),4096).unwrap());let(s,h)=observe(||field.advance(text.borrow(),4096,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(field.ready());let g=grant(field.take_demand().unwrap());let(value,_)=field.take(g).unwrap().unwrap();let identity=value.identity();let mut value=Some(value);let mut displaced=None;let mut stage=RetainedBranchProjection::<ModelIdentityState>::new();for _ in 0..10000{if stage.raw_ready(){break;}let d=stage.demand(branch,4096).unwrap();let g=grant(d);let(s,h)=observe(||stage.advance(branch,4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(stage.raw_ready());let d=RetainedBranchProjection::<ModelIdentityState>::exchange_demand::<semio_framework_value::shared_issuance::SealedShared<String>>();let g=grant(d);let((done,p),h)=observe(||stage.exchange(|r|&mut r.name,&mut value,&mut displaced,g).unwrap());assert!(done);assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));stage.begin_seal().unwrap();for _ in 0..10000{if stage.ready(){break;}let g=grant(stage.demand(branch,4096).unwrap());let(s,h)=observe(||stage.advance(branch,4096,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(stage.ready());let g=grant(stage.take_demand().unwrap());let(result,_)=stage.take(g).unwrap().unwrap();assert_eq!(result.get().name.identity(),identity);assert_eq!(result.get().name.get(),text.borrow().get());assert_eq!(result.get().version.identity(),branch.get().version.identity());assert_eq!(result.get().site.identity(),branch.get().site.identity());assert_eq!(result.get().ground_temperature.identity(),branch.get().ground_temperature.identity());assert_eq!(result.get().run_period.identity(),branch.get().run_period.identity());assert_eq!(branch.get().name.get(),law["model"]["name"].as_str().unwrap());stage.begin_close();for _ in 0..10000{if stage.terminal_is_empty(){break;}let g=grant(stage.close_demand(4096).unwrap());let(s,h)=observe(||stage.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(stage.terminal_is_empty());field.begin_close();for _ in 0..10000{if field.terminal_is_empty(){break;}let g=grant(field.close_demand(4096).unwrap());let(s,h)=observe(||field.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(field.terminal_is_empty());drain(displaced);drain(result);drain(text);drain(original);
}

#[test]
fn original_branch_projection_cancels_each_paid_prefix_without_changing_the_original(){
 use crate::state::{EnergyModelState,ModelIdentityState};
 let law=crate::state::tests::corpus();let original=source(crate::state::tests::receive::<EnergyModelState>(&law["model"]));let branch=original.borrow().project(0,|m|m.identity.get());let identity=branch.get().name.identity();for cut in 0..128{let mut stage=RetainedBranchProjection::<ModelIdentityState>::new();for _ in 0..cut{if stage.raw_ready(){break;}let d=stage.demand(branch,4096).unwrap();let g=grant(d);for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:0,..g},RetainedCloneGrant{maximum_release_bytes:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{if semio_framework_value::retained_clone::retained_clone_grant_admits(denied,d){continue;}let(s,h)=observe(||stage.advance(branch,4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(stage.demand(branch,4096).unwrap(),d);}let(s,h)=observe(||stage.advance(branch,4096,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}stage.begin_close();for _ in 0..100000{if stage.terminal_is_empty(){break;}let d=stage.close_demand(4096).unwrap();let g=grant(d);let(s,h)=observe(||stage.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(stage.terminal_is_empty());assert_eq!(observe(||drop(stage)).1,(0,0));assert_eq!(branch.get().name.identity(),identity);assert_eq!(branch.get().name.get(),law["model"]["name"].as_str().unwrap());}drain(original);
}
